// Valid: Type-safe, self-validating boundaries
struct ZipCode(String);

impl ZipCode {
    fn parse(s: String) -> Result<Self, &'static str> {
        if s.len() == 5 && s.chars().all(|c| c.is_ascii_digit()) {
            Ok(ZipCode(s))
        } else {
            Err("Invalid ZIP")
        }
    }
